// vite.config.ts — hide maps, drop a flag at compile time, don't invent 40 manualChunks
export default defineConfig({
  define: {
    __PAYMENTS_V2__: JSON.stringify(false),
  },
  build: {
    sourcemap: "hidden",
    rollupOptions: {
      plugins: [visualizer({ gzipSize: true, emitFile: true })],
    },
  },
});

